#!/usr/bin/env bash
# =============================================================================
# BillRight AI: recreate the complete project, file by file.
#
#   bash build_project.sh [target_dir]        (default: ./billright-ai)
#
# Generated by deploy/make_build_script.py. Do not edit by hand; regenerate.
# Writes 90 files (67 source files as plain text, 23 data files
# gzip+base64), then verifies every file's SHA-256.
#
# Not included: .env (secrets), trained models, cleaned data and the document
# index (the container builds them on its first start). Next: bash run_on_ec2.sh
# =============================================================================
set -euo pipefail

TARGET="${1:-./billright-ai}"
mkdir -p "$TARGET"
cd "$TARGET"
echo "Writing BillRight AI project into $(pwd)"

b64dec() { base64 -d 2>/dev/null || base64 -D; }

# ---- .dockerignore
cat > '.dockerignore' <<'__BILLRIGHT_EOF__'
.env
.git
.ppt_build
.ppt_output
database
output
processed
__pycache__
*.pyc
__BILLRIGHT_EOF__

# ---- .env.example
cat > '.env.example' <<'__BILLRIGHT_EOF__'
GEMINI_API_KEY=your-gemini-api-key
GEMINI_MODEL=gemini-3.1-flash-lite
__BILLRIGHT_EOF__

# ---- .streamlit/config.toml
mkdir -p ".streamlit"
cat > '.streamlit/config.toml' <<'__BILLRIGHT_EOF__'
