"""Recalls the last few exchanges of a person's own conversation."""
from config import config
from persistence import repository
from persistence.models import ChatTurn


def recall_conversation(session, username, question_text):
    """Give the assistant the last few exchanges of this person's own conversation."""
    turns = repository.fetch_chat_turns(session, ChatTurn.username == username,
                                        config.CHAT_HISTORY_TURN_LIMIT)
    turns = list(reversed(turns))           # oldest first
    if not turns:
        history_text = "This is the first question of the conversation."
        earlier = []
    else:
        parts = []
        for turn in turns:
            answered = (config.CHAT_STATUS_ANSWER_IN_HISTORY
                        if turn["question_type"] == config.CHAT_TYPE_DISPUTE_STATUS
                        else turn["answer_text"])
            parts.append(f"Asked: {turn['question_text']}\nAnswered: {answered}")
        history_text = "\n\n".join(parts)
        earlier = [turn["question_text"] for turn in turns]
    return {"history_text": history_text, "search_text": " ".join(earlier + [question_text])}
__BILLRIGHT_EOF__

# ---- chat/dispute_status_answer.py
mkdir -p "chat"
cat > 'chat/dispute_status_answer.py' <<'__BILLRIGHT_EOF__'
"""Answers a question about one named dispute from its record, in the way the asker's role allows."""
from config import config
from persistence import repository
from persistence.models import BillingDispute


def _answer(text):
    return {"answer": text, "source_documents": [], "was_refused": False}


def answer_dispute_status(session, open_disputes, role_name, dispute_reference):
    """Answer a question about one named dispute from its record."""
    known = (dispute_reference is not None and
             (open_disputes[config.DISPUTE_REFERENCE_COLUMN] == dispute_reference).any())
    if not known:
        return _answer(config.CHAT_UNKNOWN_DISPUTE_MESSAGE)
    records = repository.fetch_dispute_records(session, BillingDispute.dispute_reference == dispute_reference)
    figures = role_name in config.CHAT_FIGURE_ROLES
    if not records:
        text = config.CHAT_NOT_ASSESSED_TEMPLATE.format(dispute_reference=dispute_reference)
        return _answer(text if figures else text + " " + config.CHAT_AMOUNTS_IN_WRITING_MESSAGE)
    record = records[0]
    if not figures:
        changed = record["decided_at"] or record["created_at"]
        text = config.CHAT_STATUS_TEMPLATE.format(
            dispute_reference=dispute_reference,
            status_phrase=config.CHAT_STATUS_PHRASES[record["status"]],
            changed_on=changed.strftime(config.STATUS_CHANGE_TIME_FORMAT))
        return _answer(text + " " + config.CHAT_AMOUNTS_IN_WRITING_MESSAGE)
    lines = [
        f"{dispute_reference}: assessment {record['assessment_id']}, status {record['status']}.",
        f"Amount billed GBP {record['amount_billed_gbp']}, corrected charge GBP {record['corrected_charge_gbp']}, "
        f"difference GBP {record['difference_gbp']} ({record['direction']}), redress GBP {record['redress_gbp']}.",
        f"Rebill probability {record['rebill_probability']} ({record['rebill_band']}); category "
        f"{record['dispute_category']}, with the notes agreeing {record['cause_agreement']}.",
        f"Effort {record['effort_needed_hours']} hours; recommended decision {record['recommended_decision']}.",
    ]
    if record["decision"]:
        lines.append(f"Decision {record['decision']} by {record['decided_by']} ({record['decided_by_role']}); "
                     f"settled amount GBP {record['settled_amount_gbp']} ({record['settlement_direction']}).")
    return _answer("\n".join(lines))
__BILLRIGHT_EOF__

# ---- compose.yml
cat > 'compose.yml' <<'__BILLRIGHT_EOF__'
# BillRight AI: one container, dashboard on 8080, REST API on 8081.
#
#   docker compose up -d --build     start (or rebuild after a code change)
#   docker compose down              stop (data volumes are kept)
#   docker compose down -v           stop and wipe all data
#
# Ports and the bind address of the API come from .env (written by run_on_ec2.sh).
name: billright

services:
  billright:
    build: .
    image: billright-ai:latest
    container_name: billright-ai
    restart: unless-stopped
    env_file: .env
    ports:
      - "${DASHBOARD_PORT:-8080}:8080"
      # Set API_BIND=127.0.0.1 in .env to keep the API private (reach /docs over an SSH tunnel).
      - "${API_BIND:-0.0.0.0}:${API_PORT:-8081}:8081"
    volumes:
      - billright_database:/app/database     # billright.db, checkpoint.db, chroma_store
      - billright_output:/app/output         # trained models and metrics
      - billright_processed:/app/processed   # cleaned training data
    healthcheck:
      test: ["CMD-SHELL", "python -c \"from urllib.request import urlopen; urlopen('http://127.0.0.1:8080/_stcore/health', timeout=3); urlopen('http://127.0.0.1:8081/docs', timeout=3)\""]
      interval: 30s
      timeout: 10s
      retries: 3
      # The first start cleans the data, trains the models and builds the document index.
      start_period: 20m

volumes:
  billright_database:
  billright_output:
  billright_processed:
__BILLRIGHT_EOF__

